INSERT OR REPLACE INTO equipment (item_number, name, category, oem_manual, manual_url, manual_type, pm_daily, pm_weekly, pm_monthly, pm_quarterly, pm_semi_annual, pm_annual, key_pm_summary, cal_osha_sections, cal_osha_training_req, status, location, asset_tag, last_pm_date, next_pm_due)
VALUES (21, 'Genie GS-2632 Electric Scissor Lift', 'Aerial Work Platforms', 'Genie Operator''s Manual Part No. 97552 (3rd Ed) or 1261084GT; Service Manual Part No. 96316 Rev E5; Maintenance Manual Part No. 1272215GT (Oct 2024)', 'https://manuals.genielift.com/operators/english/97552.pdf', 'pdf', 'Pre-operation inspection per operator manual: check controls function test; inspect platform/rails for damage; check hydraulic fluid level; inspect tires; check battery charge level; test emergency lowering; inspect for leaks', 'Check tire condition and inflation; inspect battery connections; clean platform; check all safety labels; inspect guardrails and chains; verify horn and alarm function', 'Lubricate all grease fittings; inspect hydraulic hoses and fittings; check scissor arm wear pads; inspect limit switches; verify pothole protection system; check electrical connections; inspect extension deck (if equipped)', 'Scheduled Maintenance Inspection per OEM (every 3 months or 150 hours whichever first): full mechanical/hydraulic/electrical inspection by qualified technician; replace hydraulic return filter; check hydraulic oil condition; inspect scissor pins and bushings; test all safety systems', '', 'Annual inspection by qualified technician: full hydraulic system service; replace hydraulic oil (or per oil analysis); structural inspection of scissor arms and platform; full electrical system check; load test; replace worn wear pads; inspect all cylinders; update maintenance records', 'CRITICAL: Pre-operation inspection daily per ANSI A92.6. Quarterly/150-hour scheduled maintenance by qualified technician. Annual comprehensive inspection. Equipment shall not be used if inspection not recorded in last 13 months.', 'T8 CCR 3203 (IIPP); T8 CCR 3646 (Elevating Work Platform Operating Instructions); T8 CCR 3648 (Aerial Device Operating Instructions); T8 CCR 3314 (LOTO); T8 CCR 3380 (PPE)', 'IIPP per 3203; operator must be trained on erecting/disassembling/moving/operating/inspecting per 3646 BEFORE operation; fall protection awareness; LOTO per 3314; PPE per 3380. Training documented.', 'Active', NULL, NULL, NULL, NULL);

INSERT OR REPLACE INTO equipment (item_number, name, category, oem_manual, manual_url, manual_type, pm_daily, pm_weekly, pm_monthly, pm_quarterly, pm_semi_annual, pm_annual, key_pm_summary, cal_osha_sections, cal_osha_training_req, status, location, asset_tag, last_pm_date, next_pm_due)
VALUES (22, 'MEC 1330SE Electric Scissor Lift', 'Aerial Work Platforms', 'MEC Operator''s Manual ART_4907a (Part #94118r2); Service & Parts Manual (Part #95834 Oct 2025 or #94123-A92.6); available at mecawp.com', 'https://www.mecawp.com/wp-content/uploads/2020/05/94118.pdf', 'pdf', 'Pre-operation inspection: controls function test; check platform/guardrails; inspect hydraulic level; check battery; test emergency lowering; visual structural check; check for leaks', 'Check tire condition; inspect battery connections; clean machine; check safety labels; inspect guardrails and entry gate/chain', 'Lubricate grease fittings; inspect hydraulic hoses; check limit switches; verify pothole protection; inspect electrical connections', 'Scheduled Maintenance per OEM (every 3 months or 150 hours whichever first): full inspection by qualified technician; hydraulic/mechanical/electrical systems check; inspect scissor pins and bushings', '', 'Annual Maintenance Inspection by qualified technician (per OEM operator manual checklist): full structural inspection; hydraulic system service; electrical system test; load test; complete documentation using Annual Inspection Checklist from operator manual', 'Pre-shift inspection by operator. Quarterly/150-hour maintenance by qualified technician ONLY. Annual inspection by qualified technician ONLY. Photocopy Annual Inspection Checklist from manual for records.', 'T8 CCR 3203 (IIPP); T8 CCR 3646 (Elevating Work Platforms); T8 CCR 3648 (Aerial Devices); T8 CCR 3314 (LOTO); T8 CCR 3380 (PPE)', 'Same as Item 21 - operator training per 3646 required before operation; IIPP per 3203; LOTO per 3314; PPE per 3380.', 'Active', NULL, NULL, NULL, NULL);

INSERT OR REPLACE INTO equipment (item_number, name, category, oem_manual, manual_url, manual_type, pm_daily, pm_weekly, pm_monthly, pm_quarterly, pm_semi_annual, pm_annual, key_pm_summary, cal_osha_sections, cal_osha_training_req, status, location, asset_tag, last_pm_date, next_pm_due)
VALUES (23, 'Skyjack SJIII 3219 Electric Scissor Lift', 'Aerial Work Platforms', 'Skyjack Operation Manual (Part No. per serial range; available at techpub.skyjack.com); Service Manual Document ID 5889; Pre-Delivery/Maintenance Inspection Checklist', 'https://www.rentalex.com/wp-content/uploads/2017/04/SJ3219_Operators_Manual.pdf', 'pdf', 'Pre-operation inspection: daily visual and function test per operator manual; check controls; inspect platform/guardrails; check hydraulic level; verify battery charge; test emergency lowering; inspect for leaks', 'Check tire condition; inspect battery connections; clean machine; check labels; inspect guardrails and chains; verify horn/alarm', 'Lubricate all fittings; inspect hydraulic hoses; check limit switches; inspect electrical; verify pothole protection', 'Scheduled Maintenance every 3 months or 150 hours (whichever first): full qualified technician inspection per OEM checklist', 'Every 2 years: comprehensive scheduled maintenance inspection per OEM covering structural/hydraulic/electrical systems; load test by qualified person', 'Annual inspection: full structural/hydraulic/electrical inspection; replace hydraulic fluid and filters per OEM; load test; complete documentation. Not to be used if inspection not recorded in last 13 months.', 'Daily visual/function test. Quarterly/150-hour inspection. Annual inspection. Biennial comprehensive inspection. Machine shall not be used if annual inspection exceeds 13 months.', 'T8 CCR 3203 (IIPP); T8 CCR 3646 (Elevating Work Platforms); T8 CCR 3648 (Aerial Devices); T8 CCR 3314 (LOTO); T8 CCR 3380 (PPE)', 'Same as Items 21-22 - operator training per 3646; IIPP per 3203; LOTO per 3314; PPE per 3380.', 'Active', NULL, NULL, NULL, NULL);

INSERT OR REPLACE INTO equipment (item_number, name, category, oem_manual, manual_url, manual_type, pm_daily, pm_weekly, pm_monthly, pm_quarterly, pm_semi_annual, pm_annual, key_pm_summary, cal_osha_sections, cal_osha_training_req, status, location, asset_tag, last_pm_date, next_pm_due)
VALUES (24, 'Yale ERP030VTN36TE088 Electric Forklift (3000 lb; S/N G807N08495N)', 'Powered Industrial Trucks', 'Yale Service Repair Manual G807 ERP030VT Series; Yale Operator''s Manual ERP030VTN; available via Yale dealer. NOTE: Current link is a third-party SlideShare upload — source official PDF from Yale dealer portal.', 'https://www.slideshare.net/slideshow/yale-g807-erp030vt-lift-truck-service-repair-manual/80135258', 'webpage', 'Pre-shift inspection per OSHA: check battery charge and connections; inspect forks for damage/cracks; check tire condition; test horn/lights/backup alarm; check hydraulic level; test brakes; inspect overhead guard; check all controls; inspect load backrest', 'Check battery water level and add distilled water if needed; clean battery top; inspect hydraulic hoses for leaks; check tire wear; inspect chain condition; verify mast operation smooth through full range', 'Full lubrication per OEM grease chart; inspect brake pads/shoes; check steering components; inspect chain anchor pins; verify hydraulic cylinder operation; inspect mast rollers; check all electrical connections', 'Every 350 hours or 2 months (per Yale OEM): comprehensive PM by qualified technician - check motor brushes; inspect contactor tips; test battery specific gravity; inspect drive motor; check all bearings; verify tilt cylinder; inspect steer axle', '', 'Every 2000 hours or annually: full overhaul PM - replace hydraulic oil and filter; full brake inspection/adjustment; inspect drive axle; motor service; full electrical system check; structural inspection of mast and forks (per ANSI B56.1); load test if required; update maintenance log', 'CRITICAL: Daily pre-shift inspection is OSHA-mandated. Yale OEM specifies 8-hour (daily) / 350-hour (bimonthly) / 2000-hour (annual) PM intervals. Fork inspection for cracks per ANSI B56.1.', 'T8 CCR 3203 (IIPP); T8 CCR 3664-3668 (Powered Industrial Truck Operation and Training); T8 CCR 3314 (LOTO); T8 CCR 3380 (PPE)', 'IIPP per 3203; PIT operator training and evaluation per 3668 (formal instruction + practical training + evaluation BEFORE operation); refresher evaluation every 3 years; LOTO per 3314 for service; PPE per 3380.', 'Active', NULL, NULL, NULL, NULL);

INSERT OR REPLACE INTO equipment (item_number, name, category, oem_manual, manual_url, manual_type, pm_daily, pm_weekly, pm_monthly, pm_quarterly, pm_semi_annual, pm_annual, key_pm_summary, cal_osha_sections, cal_osha_training_req, status, location, asset_tag, last_pm_date, next_pm_due)
VALUES (25, 'Yale E50XN-27 Electric Forklift (4700 lb; S/N A268N17124N)', 'Powered Industrial Trucks', 'Yale Service Manual A268 E50XN Series; Yale Operator''s Manual E50XN-27; available via Yale dealer. NOTE: OEM manual not yet sourced — contact Yale dealer for correct A268 series documentation.', '', 'none', 'Same as Item 24: pre-shift inspection per OSHA (battery/forks/tires/controls/brakes/lights/horn/hydraulic)', 'Same as Item 24: battery water level; clean battery; inspect hydraulic hoses; tire wear; chain condition; mast operation', 'Same as Item 24: full lubrication; brake inspection; steering; chain pins; hydraulic cylinders; mast rollers; electrical connections', 'Every 350-500 hours or 2-3 months per Yale OEM: comprehensive PM by qualified technician (motor brushes/contactor tips/battery/bearings/tilt cylinder/steer axle)', '', 'Every 2000 hours or annually: full overhaul (hydraulic oil/filter change; brake service; drive axle; motor service; electrical system; structural/mast/fork inspection per ANSI B56.1; load test)', 'Same as Item 24. Higher capacity unit (4700 lb) - ensure load capacity plate visible and accurate.', 'T8 CCR 3203 (IIPP); T8 CCR 3664-3668 (PIT Operation and Training); T8 CCR 3314 (LOTO); T8 CCR 3380 (PPE)', 'Same as Item 24 - PIT training per 3668 is MANDATORY before operation.', 'Active', NULL, NULL, NULL, NULL);

INSERT OR REPLACE INTO equipment (item_number, name, category, oem_manual, manual_url, manual_type, pm_daily, pm_weekly, pm_monthly, pm_quarterly, pm_semi_annual, pm_annual, key_pm_summary, cal_osha_sections, cal_osha_training_req, status, location, asset_tag, last_pm_date, next_pm_due)
VALUES (26, 'Electric Walkie Pallet Jack (CAT/Yale type)', 'Powered Industrial Trucks', 'CAT/Yale Walkie Pallet Jack Operator''s Manual (by specific model number); reference ANSI/ITSDF B56.1', 'https://www.manualslib.com/manual/2528957/Yale-Mpb040-E.html', 'webpage', 'Pre-shift inspection: check battery charge; inspect forks; test horn; check control handle function (drive/brake/lift/lower); inspect wheels/casters; check for hydraulic leaks; test emergency disconnect/belly button reverse', 'Check battery water level; clean machine; inspect wheels for flat spots/debris; check hydraulic fluid level; inspect control handle wiring; verify brake function', 'Lubricate per OEM chart; inspect drive wheel for wear; check steer wheels; inspect hydraulic cylinder; check battery connections and cables; verify load capacity label', 'Full PM by qualified technician: check motor brushes/contactor; inspect drive unit; check controller; inspect all wiring; test brake; verify hydraulic system; check battery specific gravity', '', 'Full annual PM: drive motor service; hydraulic system service; full electrical check; structural inspection of forks; brake overhaul; replace worn wheels; battery load test', 'Daily pre-shift check required. Monthly lubrication. Quarterly qualified technician PM. Annual full service.', 'T8 CCR 3203 (IIPP); T8 CCR 3664-3668 (PIT Operation and Training); T8 CCR 3314 (LOTO); T8 CCR 3380 (PPE)', 'IIPP per 3203; PIT training per 3668 (walkie pallet jacks ARE powered industrial trucks - training is REQUIRED per Cal/OSHA); LOTO per 3314; PPE per 3380 (safety shoes).', 'Active', NULL, NULL, NULL, NULL);

INSERT OR REPLACE INTO equipment (item_number, name, category, oem_manual, manual_url, manual_type, pm_daily, pm_weekly, pm_monthly, pm_quarterly, pm_semi_annual, pm_annual, key_pm_summary, cal_osha_sections, cal_osha_training_req, status, location, asset_tag, last_pm_date, next_pm_due)
VALUES (27, 'Manual Hydraulic Pallet Jacks x2', 'Powered Industrial Trucks', 'Pallet Jack Operator''s Manual (by specific brand/model); reference ANSI/ITSDF B56.1 for manual pallet trucks', 'https://www.crown.com/content/dam/crown/pdfs/en-us/operator-manuals/pallet-trucks/pth50.pdf', 'pdf', 'Inspect forks for cracks/damage; check hydraulic pump operation (raises/holds load); inspect wheels and casters for damage; check handle pivot; verify lowering control valve function', 'Clean wheels of debris; check hydraulic fluid level (look for leaks at seals); inspect load rollers; verify fork tips not bent', 'Lubricate wheel axles and pivot points; inspect hydraulic seals for leaks; check steering linkage; inspect fork welds; verify load capacity label visible', 'Full inspection: check hydraulic cylinder for scoring; inspect all welds; check push rod and clevis pins; verify lowering valve function; inspect entry and exit rollers', '', 'Annual inspection by qualified person: full hydraulic service; replace seals if leaking; inspect structural welds; check all pins and fasteners; replace worn wheels/rollers; verify load rating; document inspection', 'Daily inspection required. Monthly lubrication. Quarterly full check. Annual documented inspection. Though manual they still require training per Cal/OSHA.', 'T8 CCR 3203 (IIPP); T8 CCR 3664 (PIT - manual pallet jacks included by some interpretations); T8 CCR 3380 (PPE)', 'IIPP per 3203; training on safe use per 3203(a)(7); PPE per 3380 (safety shoes). Note: Cal/OSHA interpretations vary on whether manual pallet jacks require full 3668 PIT training - conservative approach is to train.', 'Active', NULL, NULL, NULL, NULL);
